15: /// A fixed-capacity ring of samples in arrival order.
16: ///
17: /// Overwrites oldest-first once full, which is what the dashboard wants: a
18: /// telemetry pane shows the recent past and a run that never ends must not grow
19: /// without bound.
20: #[derive(Debug, Clone)]
21: pub struct Series {
22:     samples: Vec<Sample>,
23:     capacity: usize,
24:     /// Where the next push lands once the ring has wrapped. Meaningless until
25:     /// `samples.len() == capacity`.
26:     head: usize,
27: }
28: 
29: impl Series {
30:     /// An empty series that will hold at most `capacity` samples.
31:     ///
32:     /// A zero capacity is legal and yields a series that discards everything —
33:     /// the configuration for a channel whose sensor is not fitted on this hull.
34:     pub fn with_capacity(capacity: usize) -> Self {
35:         Self {
36:             samples: Vec::new(),
37:             capacity,
38:             head: 0,
39:         }
40:     }
41: 
42:     /// Append a reading, evicting the oldest if the ring is full.
43:     pub fn push(&mut self, s: Sample) {
44:         if self.capacity == 0 {
45:             return;
46:         }
47:         if self.samples.len() < self.capacity {
48:             self.samples.push(s);
49:         } else {
50:             self.samples[self.head] = s;
51:             self.head = (self.head + 1) % self.capacity;
52:         }
53:     }
54: 
55:     /// How many samples the series currently holds.
56:     pub fn len(&self) -> usize {
57:         self.samples.len()
58:     }
59: 
60:     pub fn is_empty(&self) -> bool {
61:         self.samples.is_empty()
62:     }
63: 
64:     /// The configured capacity, whether or not the ring has reached it.
65:     pub fn capacity(&self) -> usize {
66:         self.capacity
67:     }
