94:                 if s.value < min {
95:                     min = s.value;
96:                 }
97:                 if s.value > max {
98:                     max = s.value;
99:                 }
100:                 sum += s.value;
101:             }
102:         }
103:         if count == 0 {
104:             return WindowStats::empty();
105:         }
106:         WindowStats {
107:             count,
108:             min,
109:             max,
110:             mean: sum / count as f64,
111:         }
112:     }
