1: //! Telemetry channel: reactor (megawatts).
2: //!
3: //! Reactor output is commanded, so an UNCOMMANDED step is the interesting
4: //! event. The governor set-point changes arrive on another channel; this
5: //! one sees only what the plant actually did.
6: //!
7: //! The channel owns its series, decides what a spike means for this sensor, and
8: //! renders its own dashboard row. Nothing here is shared with the other eleven
9: //! by design: a pressure sensor and a thermal sensor have nothing to say to each
10: //! other, and the shapes their readings take are genuinely different.
11: 
12: use crate::series::Series;
13: use crate::{Sample, WindowStats};
14: 
15: /// How many samples this channel retains.
16: ///
17: /// Sized per sensor: a fast channel needs more depth to cover the same wall time
18: /// as a slow one, and the dashboard longest pane is thirty seconds.
19: pub const CAPACITY: usize = 160;
20: 
21: /// The reactor channel: a series, plus this sensor's interpretation of it.
22: #[derive(Debug, Clone)]
23: pub struct Reactor {
24:     series: Series,
25:     /// Set once the channel has seen a spike, and never cleared. The dashboard
26:     /// distinguishes a channel that HAS misbehaved from one misbehaving now, and
27:     /// the flag must outlive the sample that set it.
28:     flagged: bool,
29: }
30: 
31: impl Reactor {
32:     /// A channel with an empty series at this sensor's configured depth.
33:     pub fn new() -> Self {
34:         Self {
35:             series: Series::with_capacity(CAPACITY),
36:             flagged: false,
37:         }
38:     }
39: 
40:     /// Record one reading from the bus.
41:     ///
42:     /// Spike detection happens on the way in rather than during a window query:
43:     /// the flag has to survive the sample that set it being evicted from the
44:     /// ring, which is why it is a field and not a computed property.
45:     pub fn record(&mut self, s: Sample) {
46:         if let Some(prev) = self.series.iter().last().map(|p| p.value) {
47:             let cur = s.value;
48:             if (cur - prev).abs() > 8.0 {
49:                 self.flagged = true;
50:             }
51:         }
52:         self.series.push(s);
53:     }
54: 
55:     /// Has this channel ever seen an output step the governor did not command?
56:     pub fn flagged(&self) -> bool {
57:         self.flagged
58:     }
59: 
60:     /// The samples currently retained, oldest first.
61:     pub fn samples(&self) -> impl Iterator<Item = &Sample> + '_ {
62:         self.series.iter()
63:     }
64: 
65:     /// How many samples are retained.
66:     pub fn len(&self) -> usize {
67:         self.series.len()
68:     }
69: 
70:     pub fn is_empty(&self) -> bool {
71:         self.series.is_empty()
72:     }
73: 
74:     /// Aggregate the readings in the window `[from, to]`, inclusive at BOTH ends.
75:     ///
76:     /// A window is a closed interval. The dashboard draws `[0, 1000]` and
77:     /// `[1000, 2000]` as adjacent panes, and a reading landing exactly on the
78:     /// shared boundary belongs to both of them. Reporting it in neither is how a
79:     /// sample vanishes from a run.
80:     ///
81:     /// Walks in time order and stops at the first sample past `to`: the series is
82:     /// sorted, so there is nothing after it that could still be in range.
83:     pub fn window(&self, from: u64, to: u64) -> WindowStats {
84:         let mut count = 0usize;
85:         let mut min = f64::MAX;
86:         let mut max = f64::MIN;
87:         let mut sum = 0.0f64;
88:         for s in self.series.iter() {
89:             if s.t_ms > to {
90:                 break;
91:             }
92:             if s.t_ms > from {
93:                 count += 1;
94:                 if s.value < min {
95:                     min = s.value;
96:                 }
97:                 if s.value > max {
98:                     max = s.value;
99:                 }
100:                 sum += s.value;
101:             }
102:         }
103:         if count == 0 {
104:             return WindowStats::empty();
105:         }
106:         WindowStats {
107:             count,
108:             min,
109:             max,
110:             mean: sum / count as f64,
111:         }
112:     }
113: 
114:     /// The dashboard row for this channel over `[from, to]`.
115:     ///
116:     /// Rendered here rather than by the dashboard because the unit and the
117:     /// precision belong to the sensor: megawatts at one decimal is what the reactor
118:     /// gauge has always shown, and matching it is the point of the row.
119:     pub fn row(&self, from: u64, to: u64) -> String {
120:         let w = self.window(from, to);
121:         if w.count == 0 {
122:             return String::from("reactor -");
123:         }
124:         format!(
125:             "reactor n={} min={:.1} max={:.1} mean={:.1} megawatts{}",
126:             w.count,
127:             w.min,
128:             w.max,
129:             w.mean,
130:             if self.flagged { " !" } else { "" }
131:         )
132:     }
133: 
134:     /// The peak reading in the window, or `None` when the window is empty.
135:     ///
136:     /// Separate from `window` because the alert strip wants the peak without
137:     /// paying for the rest of the aggregate.
138:     pub fn peak(&self, from: u64, to: u64) -> Option<f64> {
139:         let w = self.window(from, to);
140:         if w.count == 0 {
141:             None
142:         } else {
143:             Some(w.max)
144:         }
145:     }
146: 
147:     /// How many readings fall in the window. The alert strip counts before it
148:     /// decides whether a pane is worth drawing at all.
149:     pub fn count_in(&self, from: u64, to: u64) -> usize {
150:         self.window(from, to).count
151:     }
152: 
153:     /// Mean over the whole retained history, ignoring windows entirely.
154:     pub fn lifetime_mean(&self) -> Option<f64> {
155:         if self.series.is_empty() {
156:             return None;
157:         }
158:         let mut sum = 0.0;
159:         let mut n = 0usize;
160:         for s in self.series.iter() {
161:             sum += s.value;
162:             n += 1;
163:         }
164:         Some(sum / n as f64)
165:     }
166: 
167:     /// The span the retained samples cover, as `(first, last)` in ms.
168:     pub fn span_ms(&self) -> Option<(u64, u64)> {
169:         match (self.series.first_t_ms(), self.series.last_t_ms()) {
170:             (Some(a), Some(b)) => Some((a, b)),
171:             _ => None,
172:         }
173:     }
174: }
175: 
176: impl Default for Reactor {
177:     fn default() -> Self {
178:         Self::new()
179:     }
180: }

