26: /// One reading, as the sensor bus delivers it.
27: #[derive(Debug, Clone, Copy, PartialEq)]
28: pub struct Sample {
29:     /// Milliseconds since the run began.
30:     pub t_ms: u64,
31:     pub value: f64,
32: }
33: 
