    ///
    /// Walks in time order and stops at the first sample past `to`: the series is
    /// sorted, so there is nothing after it that could still be in range.
    pub fn window_stats(&self, from: u64, to: u64) -> WindowStats {
        let mut count = 0usize;
        let mut min = f64::MAX;
        let mut max = f64::MIN;
        let mut sum = 0.0f64;
        for s in self.iter() {
            if s.t_ms > to {
                break;
            }
            if s.t_ms >= from {
                count += 1;
                if s.value < min {
                    min = s.value;
                }
                if s.value > max {
                    max = s.value;
                }
                sum += s.value;
            }
        }
        if count == 0 {
            return WindowStats::empty();
        }
        WindowStats {
            count,
            min,
            max,
            mean: sum / count as f64,
        }
    }
