1: //! The shared sample buffer every telemetry channel writes into.
2: //!
3: //! A `Series` is a fixed-capacity ring of `Sample`s in arrival order. The bus
4: //! delivers readings monotonically in `t_ms`, so the ring is always sorted by
5: //! time and a window query is a contiguous slice — no sorting, no scanning from
6: //! both ends.
7: //!
8: //! What lives here is deliberately narrow: storage, and the two accessors every
9: //! channel needs (`iter` and `len`). Anything that INTERPRETS a sample — what
10: //! counts as a spike, what the units mean, how to label it — belongs to the
11: //! channel that owns the sensor, not to the buffer.
12: 
13: use crate::Sample;
14: 
15: /// A fixed-capacity ring of samples in arrival order.
16: ///
17: /// Overwrites oldest-first once full, which is what the dashboard wants: a
18: /// telemetry pane shows the recent past and a run that never ends must not grow
19: /// without bound.
20: #[derive(Debug, Clone)]
21: pub struct Series {
22:     samples: Vec<Sample>,
23:     capacity: usize,
24:     /// Where the next push lands once the ring has wrapped. Meaningless until
25:     /// `samples.len() == capacity`.
26:     head: usize,
27: }
28: 
29: impl Series {
30:     /// An empty series that will hold at most `capacity` samples.
31:     ///
32:     /// A zero capacity is legal and yields a series that discards everything —
33:     /// the configuration for a channel whose sensor is not fitted on this hull.
34:     pub fn with_capacity(capacity: usize) -> Self {
35:         Self {
36:             samples: Vec::new(),
37:             capacity,
38:             head: 0,
39:         }
40:     }
41: 
42:     /// Append a reading, evicting the oldest if the ring is full.
43:     pub fn push(&mut self, s: Sample) {
44:         if self.capacity == 0 {
45:             return;
46:         }
47:         if self.samples.len() < self.capacity {
48:             self.samples.push(s);
49:         } else {
50:             self.samples[self.head] = s;
51:             self.head = (self.head + 1) % self.capacity;
52:         }
53:     }
54: 
55:     /// How many samples the series currently holds.
56:     pub fn len(&self) -> usize {
57:         self.samples.len()
58:     }
59: 
60:     pub fn is_empty(&self) -> bool {
61:         self.samples.is_empty()
62:     }
63: 
64:     /// The configured capacity, whether or not the ring has reached it.
65:     pub fn capacity(&self) -> usize {
66:         self.capacity
67:     }
68: 
69:     /// Every sample in TIME order, oldest first.
70:     ///
71:     /// Once the ring has wrapped, arrival order and storage order differ: the
72:     /// oldest live sample sits at `head`, not at index 0. Callers walking a time
73:     /// window depend on this being sorted, so the wrap is resolved here rather
74:     /// than at each call site.
75:     pub fn iter(&self) -> impl Iterator<Item = &Sample> + '_ {
76:         let (a, b) = if self.samples.len() < self.capacity {
77:             (&self.samples[..], &self.samples[..0])
78:         } else {
79:             self.samples.split_at(self.head)
80:         };
81:         b.iter().chain(a.iter())
82:     }
83: 
84:     /// The time of the oldest live sample, if any.
85:     pub fn first_t_ms(&self) -> Option<u64> {
86:         self.iter().next().map(|s| s.t_ms)
87:     }
88: 
89:     /// The time of the newest live sample, if any.
90:     pub fn last_t_ms(&self) -> Option<u64> {
91:         self.iter().last().map(|s| s.t_ms)
92:     }
93: }

