    /// The time of the newest live sample, if any.
    pub fn last_t_ms(&self) -> Option<u64> {
        self.iter().last().map(|s| s.t_ms)
    }

    /// Aggregate the readings in the window `[from, to]`, inclusive at BOTH ends.
    ///
    /// A window is a closed interval. The dashboard draws `[0, 1000]` and
    /// `[1000, 2000]` as adjacent panes, and a reading landing exactly on the
    /// shared boundary belongs to both of them. Reporting it in neither is how a
    /// sample vanishes from a run, so both endpoints are held here.
    ///
    /// Walks in time order and stops at the first sample past `to`: the series is
    /// sorted, so there is nothing after it that could still be in range.
    pub fn window_stats(&self, from: u64, to: u64) -> WindowStats {
        let mut count = 0usize;
        let mut min = f64::MAX;
        let mut max = f64::MIN;
        let mut sum = 0.0f64;
        for s in self.iter() {
            if s.t_ms > to {
                break;
            }
            if s.t_ms >= from {
                count += 1;
                if s.value < min {
                    min = s.value;
                }
                if s.value > max {
                    max = s.value;
                }
                sum += s.value;
            }
        }
        if count == 0 {
            return WindowStats::empty();
        }
        WindowStats {
            count,
            min,
            max,
            mean: sum / count as f64,
        }
    }
